function singleMailbox(value) {
  if (typeof value !== "string" || /[\r\n\x00]/.test(value)) return "";
  const text = value.trim();
  const named = text.match(/^(?:[^<>,;]+|"[^"\r\n]+")\s*<([^<>]+)>$/);
  const address = named ? named[1] : text;
  return /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+$/.test(address) &&
    address.length <= 254
    ? address
    : "";
}

const settings = {
  folder: "INBOX",
  reviewer: "reviewer@example.invalid",
  mailbox: "mailbox@example.invalid",
};
const from = settings.mailbox,
  reviewer = settings.reviewer;
if (
  !singleMailbox(from) ||
  !singleMailbox(reviewer) ||
  from.endsWith(".invalid") ||
  reviewer.endsWith(".invalid")
) {
  throw Error("Set the SMTP mailbox and reviewer addresses.");
}
return $input.all().map((item, index) => ({
  json: { ...item.json, fromEmail: from, reviewer },
  pairedItem: { item: index },
}));

