function reviewText(mail, summary, draft) {
  return (
    "Original sender: " +
    mail.sender +
    "\nSubject: " +
    mail.subject +
    "\n\nOriginal message\n" +
    mail.body +
    "\n\nSummary\n" +
    summary +
    "\n\nProposed reply\n" +
    draft
  );
}

function escapeDraftHtml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

const source = $("Check the summary and prepare the reply request").all(0, $runIndex)[0].json;
const draft = checkModelText($input.first().json.body, "draft", structuredDraftReply);
const reviewCode = String($execution.id) + "-" + source.uid;
const key = (source.fromEmail + "|" + source.sender + "|" + source.messageId).toLowerCase();
const review = reviewText(source, source.summary, draft);
return [
  {
    json: {
      ...source,
      draft,
      reviewCode,
      key,
      approvalMessage:
        '<pre style="white-space:pre-wrap">' +
        escapeDraftHtml(review) +
        "</pre><p>Review code: <strong>" +
        escapeDraftHtml(reviewCode) +
        "</strong></p>",
    },
  },
];

const original = $("Prepare the original and reply for approval").all(0, $runIndex)[0].json;
const answer = $input.first().json.data;
return [
  {
    json: {
      approved:
        answer?.Decision === "Approve" &&
        typeof answer["Review code"] === "string" &&
        answer["Review code"].trim() === original.reviewCode,
      sender: original.sender,
      subject: "Re: " + original.subject,
      text: original.draft,
      fromEmail: original.fromEmail,
      key: original.key,
    },
  },
];

const approved = $("Verify the approval code and draft").all(0, $runIndex)[0].json;
const noPrior = Object.keys($input.first().json).length === 0;
return [{ json: { ...approved, send: approved.approved && noPrior }, pairedItem: { item: 0 } }];

function smtpAccepted(result, to) {
  if (
    !result ||
    !Array.isArray(result.accepted) ||
    result.accepted.length !== 1 ||
    result.accepted[0] !== to ||
    !Array.isArray(result.rejected) ||
    result.rejected.length !== 0 ||
    typeof result.messageId !== "string" ||
    !result.messageId.trim()
  )
    throw Error(
      "SMTP acceptance could not be verified. Check mail logs before considering another send.",
    );
  return result.messageId;
}

const { sender, key } = $("Check the approved reply is new").item.json;
return [{ json: { key, messageId: smtpAccepted($input.first().json, sender) } }];
